import dis
import inspect

def clasificar_nombres(funcion):
    co = funcion.__code__
    n = co.co_argcount + co.co_kwonlyargcount
    if co.co_flags & inspect.CO_VARARGS:
        n += 1
    if co.co_flags & inspect.CO_VARKEYWORDS:
        n += 1
    parametros = set(co.co_varnames[:n])
    locales = (set(co.co_varnames) | set(co.co_cellvars)) - parametros
    globales = {
        ins.argval
        for ins in dis.get_instructions(funcion)
        if ins.opname in ("LOAD_GLOBAL", "STORE_GLOBAL", "DELETE_GLOBAL")
    }
    return {
        "parametros": parametros,
        "locales": locales,
        "libres": set(co.co_freevars),
        "globales": globales,
    }

