import weakref

class Nodo:
    def __init__(self, valor):
        self.valor = valor
        self.hijos = []
        self._padre = None            # weakref.ref al padre, o None

    @property
    def padre(self):
        if self._padre is None:
            return None
        return self._padre()          # None si el padre ya fue liberado

    def agregar(self, hijo):
        anterior = hijo.padre
        if anterior is not None:
            anterior.hijos.remove(hijo)
        hijo._padre = weakref.ref(self)
        self.hijos.append(hijo)
        return hijo

    def ruta(self):
        valores = []
        nodo = self
        while nodo is not None:
            valores.append(nodo.valor)
            nodo = nodo.padre
        return valores[::-1]

