import inspect
import weakref

class Emisor:
    def __init__(self):
        # Cada entrada es un invocable sin argumentos que devuelve el callback
        # (o None si su objeto ya murió): WeakMethod o una lambda que lo retiene.
        self._suscriptores = []

    def suscribir(self, callback):
        if inspect.ismethod(callback):
            referencia = weakref.WeakMethod(callback)
        else:
            referencia = lambda: callback           # referencia fuerte
        self._suscriptores.append(referencia)

    def _vivos(self):
        vivos = []
        for referencia in self._suscriptores:
            callback = referencia()
            if callback is not None:
                vivos.append((referencia, callback))
        self._suscriptores = [referencia for referencia, _ in vivos]
        return [callback for _, callback in vivos]

    def emitir(self, *args, **kwargs):
        return [callback(*args, **kwargs) for callback in self._vivos()]

    def desuscribir(self, callback):
        for i, referencia in enumerate(self._suscriptores):
            if referencia() == callback:
                del self._suscriptores[i]
                return
        raise ValueError("ese callback no está suscrito")

    def __len__(self):
        return len(self._vivos())

