import builtins
import dis
import operator

NULL = object()   # marcador para el hueco que CALL reserva a self

BINARIOS = {
    "+": operator.add, "-": operator.sub, "*": operator.mul,
    "/": operator.truediv, "//": operator.floordiv, "%": operator.mod,
    "**": operator.pow, "[]": operator.getitem,
}
COMPARACIONES = {
    "<": operator.lt, "<=": operator.le, "==": operator.eq,
    "!=": operator.ne, ">": operator.gt, ">=": operator.ge,
}
UNARIOS = {
    "UNARY_NEGATIVE": operator.neg, "UNARY_NOT": operator.not_,
    "UNARY_INVERT": operator.invert, "TO_BOOL": bool,
}


def _cargar_nombre(nombre, variables):
    if nombre in variables:
        return variables[nombre]
    if hasattr(builtins, nombre):
        return getattr(builtins, nombre)
    raise NameError(f"name '{nombre}' is not defined")


def ejecutar(expresion, variables=None, traza=None):
    variables = {} if variables is None else variables
    codigo = compile(expresion, "<vm>", "eval")
    instrucciones = list(dis.get_instructions(codigo))
    posicion = {ins.offset: i for i, ins in enumerate(instrucciones)}
    pila = []
    i = 0
    while True:
        ins = instrucciones[i]
        op = ins.opname
        i += 1
        if op in ("RESUME", "NOP", "NOT_TAKEN"):
            pass
        elif op in ("LOAD_CONST", "LOAD_SMALL_INT"):
            pila.append(ins.argval)
        elif op == "LOAD_NAME":
            pila.append(_cargar_nombre(ins.argval, variables))
        elif op == "LOAD_ATTR":
            pila.append(getattr(pila.pop(), ins.argval))
            if ins.arg & 1:                      # método: invocable ligado + NULL
                pila.append(NULL)
        elif op == "BINARY_OP":
            if ins.argrepr not in BINARIOS:
                raise NotImplementedError(f"BINARY_OP {ins.argrepr}")
            der, izq = pila.pop(), pila.pop()
            pila.append(BINARIOS[ins.argrepr](izq, der))
        elif op == "COMPARE_OP":
            der, izq = pila.pop(), pila.pop()
            resultado = COMPARACIONES[ins.argval](izq, der)
            pila.append(bool(resultado) if ins.arg & 16 else resultado)
        elif op == "IS_OP":
            der, izq = pila.pop(), pila.pop()
            pila.append((izq is der) != bool(ins.arg))
        elif op == "CONTAINS_OP":
            der, izq = pila.pop(), pila.pop()
            pila.append((izq in der) != bool(ins.arg))
        elif op in UNARIOS:
            pila.append(UNARIOS[op](pila.pop()))
        elif op in ("BUILD_TUPLE", "BUILD_LIST"):
            n = ins.arg
            elementos = pila[len(pila) - n:]
            del pila[len(pila) - n:]
            pila.append(tuple(elementos) if op == "BUILD_TUPLE" else elementos)
        elif op == "COPY":
            pila.append(pila[-ins.arg])
        elif op == "SWAP":
            pila[-1], pila[-ins.arg] = pila[-ins.arg], pila[-1]
        elif op == "POP_TOP":
            pila.pop()
        elif op == "PUSH_NULL":
            pila.append(NULL)
        elif op == "CALL":
            n = ins.arg
            argumentos = pila[len(pila) - n:]
            del pila[len(pila) - n:]
            self_o_null = pila.pop()
            invocable = pila.pop()
            if self_o_null is not NULL:
                argumentos.insert(0, self_o_null)
            pila.append(invocable(*argumentos))
        elif op in ("POP_JUMP_IF_FALSE", "POP_JUMP_IF_TRUE"):
            condicion = bool(pila.pop())
            if condicion == (op == "POP_JUMP_IF_TRUE"):
                i = posicion[ins.jump_target]
        elif op == "JUMP_FORWARD":
            i = posicion[ins.jump_target]
        elif op == "RETURN_VALUE":
            return pila.pop()
        else:
            raise NotImplementedError(op)
        if traza is not None:
            traza.append((op, list(pila)))

