exercises.solution:
import importlib.abc
import importlib.util
import sys

class ImportadorMemoria(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    """Finder y loader para módulos cuyo código fuente está en un diccionario."""

    def __init__(self, fuentes):
        self.fuentes = dict(fuentes)
        self.ejecuciones = {}

    def _es_paquete(self, nombre):
        prefijo = nombre + "."
        return any(otro.startswith(prefijo) for otro in self.fuentes)

    # ---- finder ----
    def find_spec(self, fullname, path, target=None):
        if fullname not in self.fuentes:
            return None                   # que pruebe el siguiente finder
        return importlib.util.spec_from_loader(
            fullname,
            self,
            origin=f"memoria://{fullname}",
            is_package=self._es_paquete(fullname),
        )

    # ---- loader ----
    def create_module(self, spec):
        return None                       # módulo estándar

    def exec_module(self, module):
        nombre = module.__spec__.name
        codigo = compile(self.fuentes[nombre], f"memoria://{nombre}", "exec")
        self.ejecuciones[nombre] = self.ejecuciones.get(nombre, 0) + 1
        exec(codigo, module.__dict__)

    # ---- instalación ----
    def instalar(self):
        if self not in sys.meta_path:
            sys.meta_path.insert(0, self)
        return self

    def desinstalar(self):
        if self in sys.meta_path:
            sys.meta_path.remove(self)
        for nombre, modulo in list(sys.modules.items()):
            spec = getattr(modulo, "__spec__", None)
            if spec is not None and spec.loader is self:
                del sys.modules[nombre]

    def __enter__(self):
        return self.instalar()

    def __exit__(self, *exc):
        self.desinstalar()
        return False

